set-variable.value:
@{
        var body = context.Request.Body?.As<JObject>(preserveContent: true);
        var q = body?["query"]?.ToString();
        return q ?? string.Empty;
    }

return-response.set-body:
@{
            return new JObject(
              new JProperty("error", "VALIDATION_ERROR"),
              new JProperty("message", "query is required and must be a non-empty string."),
              new JProperty("correlationId", (string)context.Variables.GetValueOrDefault("correlationId","unknown"))
            ).ToString();
          }

trace.message:
@{
        return new JObject(
          new JProperty("event", "mcp_tool_call"),
          new JProperty("requestType", "mcp_tool_call"),
          new JProperty("mcpServer", "web-search-mcp"),
          new JProperty("tool", "searchWeb"),
          new JProperty("correlationId", (string)context.Variables.GetValueOrDefault("correlationId","unknown")),
          new JProperty("consumerTier", context.Request.Headers.GetValueOrDefault("x-consumer-tier","unknown")),
          new JProperty("httpStatus", context.Response.StatusCode)
        ).ToString(Newtonsoft.Json.Formatting.None);
      }

on-error.set-body:
@{
      return new JObject(
        new JProperty("error", "SEARCH_GATEWAY_ERROR"),
        new JProperty("message", "The web-search request could not be completed."),
        new JProperty("correlationId", (string)context.Variables.GetValueOrDefault("correlationId","unknown"))
      ).ToString();
    }
